import {recipes,layer} from './ingredients.js';
import {categories,products} from './products.js';
// Single source of truth (choosing another product or adding to the cart starts the card over; the cart stays): { screen: 'cardapio' or 'carrinho' (#carrinho; the category stays the last one seen), category: 'hamburgueres' or a key of categories, product: Receita id, editing, removed: applied ids, draft: ids in the open editor, combo, drink: Bebida do combo ('' until chosen; only with the combo), drinkError: the combo was added without a drink, qty: Quantidade (1-99), picks: per photo category, its selected product and Quantidade, cart: Items, each with its unit price (with the combo); the Carrinho edits their Quantidade, combo and drink by index (itemQty, itemCombo, itemDrink) without merging them }.
// The card's default (on load, on choosing another burger and after adding): no combo, no drink, Quantidade 1, no Personalização. Switching categories keeps every card as it was.
const fresh={removed:[],draft:[],editing:false,combo:false,drink:'',drinkError:false,qty:1};
export const initial={screen:'cardapio',category:'hamburgueres',product:'whopper',...fresh,picks:Object.fromEntries(Object.entries(categories).map(([k,c])=>[k,{product:c.initial,qty:1}])),cart:[]};
/** Selected product and Quantidade of the current photo category; null on Hambúrgueres. */
export const pick=s=>s.picks[s.category]??null;
const setPick=(s,v)=>({...s,picks:{...s.picks,[s.category]:{...pick(s),...v}}});
/** Same Item: product, Personalização, combo and drink; it then adds to the quantity already in the cart. */
const same=(a,b)=>a.product===b.product&&a.combo===b.combo&&a.drink===b.drink&&[...a.removed].sort().join()===[...b.removed].sort().join();
const addItem=(cart,item)=>{const i=cart.findIndex(c=>same(c,item));return i<0?[...cart,item]:cart.map((c,j)=>j===i?{...c,qty:c.qty+item.qty}:c)};
const clampQty=n=>Math.max(1,Math.min(99,n));
function photoReducer(s,a){const p=pick(s);switch(a.type){case'select':return p.product===a.product||!categories[s.category].products.some(x=>x.id===a.product)?s:setPick(s,{product:a.product,qty:1});case'qty':return setPick(s,{qty:clampQty(a.value)});case'add':return {...setPick(s,{qty:1}),cart:addItem(s.cart,{product:p.product,removed:[],combo:false,drink:'',qty:p.qty,price:products[p.product].price})};default:return s}}
/** Editing an Item in the Carrinho (index `a.index`): Quantidade, combo (unchecking clears the drink) and drink. Never merges Items. */
function itemReducer(s,a){const edit=f=>({...s,cart:s.cart.map((c,j)=>j===a.index?f(c):c)});const burger=c=>!!recipes[c.product];switch(a.type){case'itemQty':return edit(c=>({...c,qty:clampQty(a.value)}));case'itemCombo':return edit(c=>burger(c)?{...c,combo:a.value,drink:a.value?c.drink:'',price:recipes[c.product].price+(a.value?comboFee:0)}:c);case'itemDrink':return edit(c=>c.combo&&drinks.includes(a.value)?{...c,drink:a.value}:c);default:return s}}
export function reducer(s,a){if(a.type.startsWith('item'))return itemReducer(s,a);if(a.type==='category')return a.category==='carrinho'?{...s,screen:'carrinho'}:{...s,screen:'cardapio',category:categories[a.category]?a.category:'hamburgueres'};if(pick(s)&&['select','qty','add'].includes(a.type))return photoReducer(s,a);switch(a.type){case'select':return s.product===a.product||!recipes[a.product]?s:{...s,...fresh,product:a.product};case'open':return {...s,editing:true,draft:[...s.removed]};case'toggle':if(!s.editing||layer(recipes[s.product],a.id)?.locked)return s;return {...s,draft:s.draft.includes(a.id)?s.draft.filter(x=>x!==a.id):[...s.draft,a.id]};case'remove':return s.draft.includes(a.id)?s:reducer(s,{type:'toggle',id:a.id});case'reset':return {...s,draft:[]};case'apply':return {...s,editing:false,removed:[...s.draft]};case'cancel':return {...s,editing:false,draft:[]};case'combo':return {...s,combo:a.value,drink:a.value?s.drink:'',drinkError:false};case'qty':return {...s,qty:clampQty(a.value)};case'drink':return s.combo?{...s,drink:a.value,drinkError:false}:s;case'add':if(s.combo&&!s.drink)return {...s,drinkError:true};return {...s,...fresh,cart:addItem(s.cart,{product:s.product,removed:[...s.removed],combo:s.combo,drink:s.drink,qty:s.qty,price:price(s)})};default:return s}}
export const comboFee=1200,drinks=['Coca-Cola','Coca-Cola Zero','Sprite','Fanta Laranja','Natural One Laranja','Natural One Uva','Água de Copo'],money=n=>(n/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'}),price=s=>recipes[s.product].price+(s.combo?comboFee:0);
/** Total do item of the card on screen: unit price × Quantidade. */
export const itemTotal=s=>{const p=pick(s);return p?products[p.product].price*p.qty:price(s)*s.qty};
/** Name of the product an Item holds, burger or photo-only. */
export const itemName=item=>(recipes[item.product]??products[item.product]).name;
